magiccheck(struct magic_set *ms, struct magic *m)
{
        uint64_t l = m->value.q;
        uint64_t v;
        float fl, fv;
        double dl, dv;
        int matched;
        union VALUETYPE *p = &ms->ms_value;

        switch (m->type) {
        case FILE_BYTE:
                v = p->b;
                break;

        case FILE_SHORT:
        case FILE_BESHORT:
        case FILE_LESHORT:
                v = p->h;
                break;

        case FILE_LONG:
        case FILE_BELONG:
        case FILE_LELONG:
        case FILE_MELONG:
        case FILE_DATE:
        case FILE_BEDATE:
        case FILE_LEDATE:
        case FILE_MEDATE:
        case FILE_LDATE:
        case FILE_BELDATE:
        case FILE_LELDATE:
        case FILE_MELDATE:
                v = p->l;
                break;

        case FILE_QUAD:
        case FILE_LEQUAD:
        case FILE_BEQUAD:
        case FILE_QDATE:
        case FILE_BEQDATE:
        case FILE_LEQDATE:
        case FILE_QLDATE:
        case FILE_BEQLDATE:
        case FILE_LEQLDATE:
        case FILE_QWDATE:
        case FILE_BEQWDATE:
        case FILE_LEQWDATE:
                v = p->q;
                break;

        case FILE_FLOAT:
        case FILE_BEFLOAT:
        case FILE_LEFLOAT:
                fl = m->value.f;
                fv = p->f;
                switch (m->reln) {
                case 'x':
                        matched = 1;
                        break;

                case '!':
                        matched = fv != fl;
                        break;

                case '=':
                        matched = fv == fl;
                        break;

                case '>':
                        matched = fv > fl;
                        break;

                case '<':
                        matched = fv < fl;
                        break;

                default:
                        file_magerror(ms, "cannot happen with float: invalid relation `%c'",
                            m->reln);
                        return -1;
